export namespace PlatformerModel {
    let name: string;
    let targetTickRate: number;
    namespace config {
        let gravity: number;
        let gravityRising: number;
        let gravityFalling: number;
        let maxSpeed: number;
        let groundAccel: number;
        let airAccel: number;
        let friction: number;
        let stopSpeed: number;
        let jumpVelocity: number;
        let groundAngleThreshold: number;
    }
    /**
     * Determine if surface is walkable ground
     * Platformer characters can walk on steeper slopes than FPS characters
     *
     * @param {number} surfaceAngle - Angle from up vector in radians
     * @returns {boolean} - True if walkable ground
     */
    function isGround(surfaceAngle: number): boolean;
    /**
     * Ground movement physics
     * Snappy acceleration with high friction for instant stops
     *
     * @param {THREE.Vector3} velocity - Current velocity (modified in place)
     * @param {THREE.Vector3} wishDir - Input direction
     * @param {number} wishSpeed - Input magnitude (0-1)
     * @param {number} delta - Time step
     */
    function groundMove(velocity: THREE.Vector3, wishDir: THREE.Vector3, wishSpeed: number, delta: number): void;
    /**
     * Air movement physics
     * Fixed gravity with good air control for precision platforming
     *
     * @param {THREE.Vector3} velocity - Current velocity (modified in place)
     * @param {THREE.Vector3} wishDir - Input direction
     * @param {number} wishSpeed - Input magnitude (0-1)
     * @param {number} delta - Time step
     */
    function airMove(velocity: THREE.Vector3, wishDir: THREE.Vector3, wishSpeed: number, delta: number): void;
    /**
     * Clip velocity against surface
     * Standard clip without overbounce
     *
     * @param {THREE.Vector3} velocity - Current velocity (modified in place)
     * @param {THREE.Vector3} normal - Surface normal
     */
    function clipVelocity(velocity: THREE.Vector3, normal: THREE.Vector3): void;
    /**
     * Handle jump
     * Higher jump for platformer gameplay
     *
     * @param {THREE.Vector3} velocity - Current velocity (modified in place)
     * @param {boolean} onGround - Whether player is on ground
     * @returns {boolean} - True if jump was executed
     */
    function jump(velocity: THREE.Vector3, onGround: boolean): boolean;
}
